{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitchx_segment_enrolment AS ( WITH MemID_to_Shopify_pre AS ( SELECT DISTINCT TRIM(ros.mem_id) AS mem_id, TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) AS shopify_user_id FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros WHERE ros.mem_id IS NOT NULL AND ros.mem_id <> \'NaN\' AND ros.mem_id NOT IN (\'9999999999\',\'1111111111\',\'1231231231\', \'1234567890\',\'5555555555\',\'1234567891\') AND ros.shopify_user_id IS NOT NULL UNION SELECT DISTINCT TRIM(ros.mem_id) AS mem_id, TRIM(REGEXP_REPLACE(f.customer_id, \',\', \'\')) AS shopify_user_id FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros JOIN snitch_db.maplemonk.FACT_ITEMS_SNITCH f ON RIGHT(REGEXP_REPLACE(f.phone, \'[^0-9]\', \'\'), 10) = RIGHT(REGEXP_REPLACE(ros.mem_id, \'[^0-9]\', \'\'), 10) WHERE ros.mem_id IS NOT NULL AND ros.mem_id <> \'NaN\' AND ros.mem_id NOT IN (\'9999999999\',\'1111111111\',\'1231231231\', \'1234567890\',\'5555555555\',\'1234567891\') AND f.customer_id IS NOT NULL ), MemID_to_Shopify AS ( SELECT mem_id, MAX(shopify_user_id) AS shopify_user_id FROM MemID_to_Shopify_pre WHERE shopify_user_id IS NOT NULL GROUP BY mem_id ), offline_base AS ( SELECT map.shopify_user_id, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN CASE WHEN ros.vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') END AS order_ts, \'Offline\' AS channel, TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_value),\'[^0-9\.]\',\'\')) AS amt, bill_no as order_name FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros LEFT JOIN MemID_to_Shopify map ON ros.mem_id = map.mem_id WHERE COALESCE(ros.shopify_user_id, map.shopify_user_id) IS NOT NULL ), online_base AS ( SELECT TRIM(customer_id) AS shopify_user_id, CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', MIN(order_timestamp)) AS ord_ts, \'Online\' AS channel, SUM(IFNULL(gross_sales,0)) AS amt, REGEXP_REPLACE(REPLACE(order_name,\'#\',\'\'), \'\\.0$\') as order_name FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE LOWER(order_status) NOT LIKE \'%cancel%\' AND gross_sales > 0 AND tags NOT IN (\'FLITS_LOGICERP\') GROUP BY shopify_user_id, REGEXP_REPLACE(REPLACE(order_name,\'#\',\'\'), \'\\.0$\') ), all_orders AS ( SELECT * FROM online_base UNION ALL SELECT * FROM offline_base ), ranked_orders AS ( SELECT ao.*, ROW_NUMBER() OVER (PARTITION BY shopify_user_id ORDER BY ord_ts) AS rn, SUM(amt) OVER ( PARTITION BY shopify_user_id ORDER BY ord_ts RANGE BETWEEN INTERVAL \'365 day\' PRECEDING AND INTERVAL \'1 second\' PRECEDING ) AS past_spend FROM all_orders ao WHERE ord_ts >= TO_TIMESTAMP_NTZ(\'2024-02-01 00:00:00\') ), eligibility_event AS ( SELECT shopify_user_id, MIN(ord_ts) AS eligibility_ts FROM ( SELECT shopify_user_id, ord_ts, COALESCE(past_spend, 0) + amt AS spend_after FROM ranked_orders ) WHERE spend_after >= 5000 GROUP BY shopify_user_id ), enrollments AS ( SELECT TRIM(shopify_user_id) AS shopify_user_id, CASE WHEN membership_enrolled_date IS NOT NULL AND TRIM(membership_enrolled_date) <> \'\' THEN CONVERT_TIMEZONE( \'UTC\',\'Asia/Kolkata\', CASE WHEN membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP( CONCAT(TRIM(membership_enrolled_date),\':00\'), \'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(membership_enrolled_date)) END ) END AS enrolled_at FROM snitch_db.maplemonk.s3_bucket_wallet_db WHERE membership_plan = \'SILVER\' ), orders_classified AS ( SELECT r.shopify_user_id, r.channel, r.ord_ts, r.amt, r.order_name, elig.eligibility_ts, enr.enrolled_at, CASE WHEN enr.enrolled_at IS NOT NULL AND r.ord_ts >= enr.enrolled_at THEN NULL WHEN r.ord_ts <= DATEADD(day, 7, elig.eligibility_ts) AND r.rn = 1 AND r.amt >= 5000 THEN \'new\' WHEN r.ord_ts <= DATEADD(day, 7, elig.eligibility_ts) THEN \'existing_new_eligible\' WHEN elig.eligibility_ts IS NULL OR r.ord_ts < elig.eligibility_ts THEN \'below_eligible\' ELSE \'existing_eligible\' END AS segment_type FROM ranked_orders r LEFT JOIN eligibility_event elig USING (shopify_user_id) LEFT JOIN enrollments enr USING (shopify_user_id) WHERE elig.eligibility_ts IS NOT NULL ) SELECT shopify_user_id, DATE_TRUNC(\'week\', ord_ts)::date AS ord_week, ord_ts, channel, order_name, segment_type, amt, CASE WHEN enrolled_at IS NOT NULL AND ord_ts <= enrolled_at THEN 1 ELSE 0 END AS enrolled_after_order FROM orders_classified WHERE segment_type IS NOT NULL and ord_ts > \'2025-02-04\' ORDER BY ord_ts); CREATE OR REPLACE TABLE snitchx_daily_summary AS ( WITH creator_users AS ( SELECT DISTINCT shopify_user_id FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db WHERE LOWER(reason) LIKE \'%creator%\' ), SnitchX_Members AS ( SELECT TRIM(shopify_user_id) AS shopify_user_id, CONVERT_TIMEZONE( \'UTC\',\'Asia/Kolkata\', CASE WHEN membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP( CONCAT(membership_enrolled_date,\':00\'), \'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(membership_enrolled_date) END ) AS snitchx_ts FROM snitch_db.maplemonk.s3_bucket_wallet_db WHERE membership_plan = \'SILVER\' ), post_online AS ( SELECT DATE_TRUNC(day, order_timestamp) AS order_date, order_timestamp AS order_ts, \'Online\' AS channel, REPLACE(order_name,\'#\',\'\') AS order_id, TRIM(customer_id) AS shopify_user_id, SUM(gross_sales) AS gross_sales, SUM(discount) - SUM(slashed_discount) AS discounts, SUM(CASE WHEN IS_REFUND = 0 THEN gross_sales ELSE 0 END) AS net_sales, SUM(quantity) AS qty FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH fi JOIN SnitchX_Members sm ON fi.customer_id = sm.shopify_user_id WHERE order_timestamp > sm.snitchx_ts AND LOWER(order_status) NOT LIKE \'%cancel%\' AND gross_sales <> 0 AND LOWER(tags) NOT LIKE \'%creator%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' AND customer_id NOT IN (SELECT shopify_user_id FROM creator_users) GROUP BY order_date, order_ts, order_name, customer_id ), post_offline AS ( SELECT DATE_TRUNC(day, vouch_ts) AS order_date, vouch_ts AS order_ts, \'Offline\' AS channel, bill_no AS order_id, TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) AS shopify_user_id, TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.]\',\'\')) AS gross_sales, TRY_TO_NUMBER(REGEXP_REPLACE(discount ,\'[^0-9.]\',\'\')) AS discounts, TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.]\',\'\')) AS net_sales, NULL AS qty FROM ( SELECT ros.*, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN IFF(ros.vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') END AS vouch_ts FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros WHERE TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(ros.bill_value),\'[^0-9.]\',\'\')) > 0 ) ros JOIN SnitchX_Members sm ON TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) = sm.shopify_user_id WHERE vouch_ts > sm.snitchx_ts AND ros.shopify_user_id NOT IN (SELECT shopify_user_id FROM creator_users) ), pre_last_online AS ( WITH latest_order AS ( SELECT customer_id, REPLACE(order_name,\'#\',\'\') AS order_id, order_timestamp, ROW_NUMBER() OVER ( PARTITION BY customer_id ORDER BY order_timestamp DESC) AS rn FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH fi JOIN SnitchX_Members sm ON fi.customer_id = sm.shopify_user_id WHERE fi.gross_sales > 0 AND order_timestamp <= sm.snitchx_ts AND DATEDIFF(day, order_timestamp, sm.snitchx_ts) < 4 AND LOWER(order_status) NOT LIKE \'%cancel%\' AND customer_id NOT IN (SELECT shopify_user_id FROM creator_users) ) , last_per_user AS ( SELECT customer_id, order_id FROM latest_order WHERE rn = 1 ) SELECT DATE_TRUNC(day, fi.order_timestamp) AS order_date, fi.order_timestamp AS order_ts, \'Online\' AS channel, REPLACE(fi.order_name,\'#\',\'\') AS order_id, TRIM(fi.customer_id) AS shopify_user_id, SUM(fi.gross_sales) AS gross_sales, SUM(fi.discount) - SUM(fi.slashed_discount) AS discounts, SUM(CASE WHEN fi.IS_REFUND = 0 THEN fi.gross_sales ELSE 0 END) AS net_sales, SUM(fi.quantity) AS qty FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH fi JOIN last_per_user lu ON fi.customer_id = lu.customer_id AND REPLACE(fi.order_name,\'#\',\'\') = lu.order_id GROUP BY order_date, fi.order_timestamp, fi.order_name, fi.customer_id ), pre_last_offline AS ( WITH ranked AS ( SELECT DATE_TRUNC(day, vouch_ts) AS order_date, vouch_ts AS order_ts, \'Offline\' AS channel, bill_no AS order_id, TRIM(REGEXP_REPLACE(shopify_user_id, \',\', \'\')) AS shopify_user_id, TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\')) AS gross_sales, TRY_TO_NUMBER(REGEXP_REPLACE(discount,\'[^0-9.-]\',\'\')) AS discounts, TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\')) AS net_sales, NULL AS qty, ROW_NUMBER() OVER ( PARTITION BY TRIM(REGEXP_REPLACE(shopify_user_id, \',\', \'\')) ORDER BY vouch_ts DESC) AS rn FROM ( SELECT ros.*, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN IFF(ros.vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(ros.transaction_date,\'MON DD, YYYY, HH12:MI AM\') END AS vouch_ts FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros JOIN SnitchX_Members sm ON TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) = sm.shopify_user_id WHERE CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN IFF(ros.vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(ros.transaction_date,\'MON DD, YYYY, HH12:MI AM\') END <= sm.snitchx_ts AND DATEDIFF( day, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN IFF(ros.vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(ros.transaction_date,\'MON DD, YYYY, HH12:MI AM\') END, sm.snitchx_ts) < 4 AND ros.shopify_user_id NOT IN (SELECT shopify_user_id FROM creator_users) ) ) SELECT order_date, order_ts, channel, order_id, shopify_user_id, gross_sales, discounts, net_sales, qty FROM ranked WHERE rn = 1 ), combined_orders AS ( SELECT * FROM post_online UNION ALL SELECT * FROM post_offline UNION ALL SELECT * FROM pre_last_online UNION ALL SELECT * FROM pre_last_offline ), base_day_totals AS ( SELECT CAST(order_timestamp AS DATE) AS order_date, COUNT(DISTINCT REPLACE(order_name,\'#\',\'\')) AS total_orders, COUNT(DISTINCT customer_id) AS total_users, SUM(gross_sales) AS total_revenue FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE gross_sales > 0 AND LOWER(order_status) NOT LIKE \'%cancel%\' GROUP BY order_date UNION ALL SELECT CAST( CASE WHEN vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN IFF(vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(transaction_date,\'MON DD, YYYY, HH12:MI AM\') END AS DATE) AS order_date, COUNT(DISTINCT bill_no) AS total_orders, COUNT(DISTINCT TRIM(REGEXP_REPLACE(shopify_user_id,\',\',\'\'))) AS total_users, SUM(TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\'))) AS total_revenue FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary GROUP BY order_date ), base_day_totals_collapsed AS ( SELECT order_date, SUM(total_orders) AS total_orders, SUM(total_users) AS total_users, SUM(total_revenue) AS total_revenue FROM base_day_totals GROUP BY order_date ), base_day_totals_by_channel AS ( SELECT order_date, SUM(CASE WHEN channel = \'Online\' THEN total_orders END) AS total_online_orders, SUM(CASE WHEN channel = \'Offline\' THEN total_orders END) AS total_offline_orders, SUM(CASE WHEN channel = \'Online\' THEN total_users END) AS total_online_users, SUM(CASE WHEN channel = \'Offline\' THEN total_users END) AS total_offline_users, SUM(CASE WHEN channel = \'Online\' THEN total_revenue END) AS total_online_revenue, SUM(CASE WHEN channel = \'Offline\' THEN total_revenue END) AS total_offline_revenue FROM ( SELECT CAST(order_timestamp AS DATE) AS order_date, \'Online\' AS channel, COUNT(DISTINCT REPLACE(order_name,\'#\',\'\')) AS total_orders, COUNT(DISTINCT customer_id) AS total_users, SUM(gross_sales) AS total_revenue FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE gross_sales > 0 AND LOWER(order_status) NOT LIKE \'%cancel%\' GROUP BY order_date UNION ALL SELECT CAST( CASE WHEN vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN IFF(vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(transaction_date,\'MON DD, YYYY, HH12:MI AM\') END AS DATE) AS order_date, \'Offline\' AS channel, COUNT(DISTINCT bill_no) AS total_orders, COUNT(DISTINCT TRIM(REGEXP_REPLACE(shopify_user_id,\',\',\'\'))) AS total_users, SUM(TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\'))) AS total_revenue FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary GROUP BY order_date ) GROUP BY order_date ) SELECT co.order_date, co.order_ts, s.snitchx_ts, co.channel, co.order_id, co.shopify_user_id, co.gross_sales, co.discounts, co.net_sales, co.qty, bdt.total_orders, bdt.total_users, bdt.total_revenue, bdc.total_online_orders, bdc.total_offline_orders, bdc.total_online_users, bdc.total_offline_users, bdc.total_online_revenue, bdc.total_offline_revenue FROM combined_orders co LEFT JOIN SnitchX_Members s ON co.shopify_user_id = s.shopify_user_id LEFT JOIN base_day_totals_collapsed bdt ON co.order_date = bdt.order_date LEFT JOIN base_day_totals_by_channel bdc ON co.order_date = bdc.order_date ORDER BY co.order_date, co.order_id ) ; CREATE OR REPLACE TABLE snitchx_monthly_summary AS ( WITH creator_users AS ( SELECT DISTINCT shopify_user_id FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db WHERE LOWER(reason) LIKE \'%creator%\' ), SnitchX_Members AS ( SELECT TRIM(shopify_user_id) AS shopify_user_id, CONVERT_TIMEZONE( \'UTC\',\'Asia/Kolkata\', CASE WHEN membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP( CONCAT(membership_enrolled_date,\':00\'), \'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(membership_enrolled_date) END ) AS snitchx_ts FROM snitch_db.maplemonk.s3_bucket_wallet_db WHERE membership_plan = \'SILVER\' ), coins_redeemed AS ( SELECT DATE_TRUNC( month, TRY_TO_TIMESTAMP(created_at, \'YYYY-MM-DD HH24:MI:SS.FF3\') ) AS month, SUM(ABS(amount)) AS coins_value FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db WHERE membership_plan = \'SILVER\' AND type = \'POINTS_DEBIT\' AND reason IN (\'Purchase : Online\',\'Purchase : Store\') AND shopify_user_id NOT IN (SELECT shopify_user_id FROM creator_users) GROUP BY month ), freebie_cost AS ( SELECT DATE_TRUNC( month, TRY_TO_TIMESTAMP(streak_timestamp,\'DD-MM-YYYY HH24:MI\') ) AS month, COUNT(*) * 300 AS freebie_value FROM snitch_db.maplemonk.streaks_streaks WHERE gift_reference_id != \'\' AND shopify_user_id NOT IN (SELECT shopify_user_id FROM creator_users) AND streak_timestamp IS NOT NULL GROUP BY month ), coins_plus_freebie AS ( SELECT COALESCE(c.month,f.month) AS month, COALESCE(c.coins_value ,0) AS coins_value, COALESCE(f.freebie_value,0) AS freebie_value, COALESCE(c.coins_value ,0)+COALESCE(f.freebie_value,0) AS combined_value FROM coins_redeemed c FULL OUTER JOIN freebie_cost f USING (month) ), post_online AS ( SELECT DATE_TRUNC(month, order_timestamp) AS month, order_timestamp AS order_ts, \'Online\' AS channel, REPLACE(order_name,\'#\',\'\') AS order_id, TRIM(customer_id) AS shopify_user_id, SUM(gross_sales) AS gross_sales, SUM(discount) - SUM(slashed_discount) AS discounts, SUM(CASE WHEN IS_REFUND = 0 THEN gross_sales ELSE 0 END) AS net_sales, SUM(quantity) AS qty FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH fi JOIN SnitchX_Members sm ON fi.customer_id = sm.shopify_user_id WHERE order_timestamp > sm.snitchx_ts AND LOWER(order_status) NOT LIKE \'%cancel%\' AND gross_sales <> 0 AND LOWER(tags) NOT LIKE \'%creator%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' AND customer_id NOT IN (SELECT shopify_user_id FROM creator_users) GROUP BY month, order_ts, order_name, customer_id ), post_offline AS ( SELECT DATE_TRUNC(month, vouch_ts) AS month, vouch_ts AS order_ts, \'Offline\' AS channel, bill_no AS order_id, TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) as shopify_user_id, TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\')) AS gross_sales, TRY_TO_NUMBER(REGEXP_REPLACE(discount ,\'[^0-9.-]\',\'\')) AS discounts, TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\')) AS net_sales, NULL AS qty FROM ( SELECT ros.*, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN CASE WHEN ros.vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') END AS vouch_ts FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros ) ros JOIN SnitchX_Members sm ON TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) = sm.shopify_user_id WHERE vouch_ts > sm.snitchx_ts AND ros.shopify_user_id NOT IN (SELECT shopify_user_id FROM creator_users) ), pre_last_online AS ( WITH latest_order AS ( SELECT customer_id, REPLACE(order_name,\'#\',\'\') AS order_id, order_timestamp, ROW_NUMBER() OVER ( PARTITION BY customer_id ORDER BY order_timestamp DESC ) AS rn FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH fi JOIN SnitchX_Members sm ON fi.customer_id = sm.shopify_user_id WHERE fi.gross_sales > 0 AND DATEDIFF(day, order_timestamp, sm.snitchx_ts) < 4 AND order_timestamp <= sm.snitchx_ts AND LOWER(order_status) NOT LIKE \'%cancel%\' AND customer_id NOT IN (SELECT shopify_user_id FROM creator_users) ), last_per_user AS ( SELECT customer_id, order_id FROM latest_order WHERE rn = 1 ) SELECT DATE_TRUNC(month, fi.order_timestamp) AS month, fi.order_timestamp AS order_ts, \'Online\' AS channel, REPLACE(fi.order_name,\'#\',\'\') AS order_id, TRIM(fi.customer_id) AS shopify_user_id, SUM(fi.gross_sales) AS gross_sales, SUM(fi.discount) - SUM(fi.slashed_discount) AS discounts, SUM(CASE WHEN fi.IS_REFUND = 0 THEN fi.gross_sales ELSE 0 END) AS net_sales, SUM(fi.quantity) AS qty FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH fi JOIN last_per_user lu ON fi.customer_id = lu.customer_id AND REPLACE(fi.order_name,\'#\',\'\') = lu.order_id GROUP BY month, fi.order_timestamp, fi.order_name, fi.customer_id ), pre_last_offline AS ( SELECT DATE_TRUNC(month, vouch_ts) AS month, vouch_ts AS order_ts, \'Offline\' AS channel, bill_no AS order_id, TRIM(REGEXP_REPLACE(shopify_user_id, \',\', \'\')) AS shopify_user_id, TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\')) AS gross_sales, TRY_TO_NUMBER(REGEXP_REPLACE(discount ,\'[^0-9.-]\',\'\')) AS discounts, TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\')) AS net_sales, NULL AS qty FROM ( SELECT ros.*, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN CASE WHEN ros.vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') END AS vouch_ts, ROW_NUMBER() OVER ( PARTITION BY ros.shopify_user_id ORDER BY CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN CASE WHEN ros.vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') END DESC ) AS rn FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros JOIN SnitchX_Members sm ON TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) = sm.shopify_user_id WHERE CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN CASE WHEN ros.vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') END <= sm.snitchx_ts AND DATEDIFF( day, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN CASE WHEN ros.vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date,\'MON DD, YYYY, HH12:MI AM\') END, sm.snitchx_ts ) < 4 AND ros.shopify_user_id NOT IN (SELECT shopify_user_id FROM creator_users) ) WHERE rn = 1 ), latest_pre_order AS ( WITH pooled AS ( SELECT month, order_ts, channel, order_id, shopify_user_id, gross_sales, discounts, net_sales, qty FROM pre_last_online UNION ALL SELECT month, order_ts, channel, order_id, shopify_user_id, gross_sales, discounts, net_sales, qty FROM pre_last_offline ), ranked AS ( SELECT p.*, ROW_NUMBER() OVER ( PARTITION BY shopify_user_id ORDER BY order_ts DESC ) AS rn FROM pooled p ) SELECT month, order_ts, channel, order_id, shopify_user_id, gross_sales, discounts, net_sales, qty FROM ranked WHERE rn = 1 ), combined_orders AS ( SELECT * FROM post_online UNION ALL SELECT * FROM post_offline UNION ALL SELECT * FROM latest_pre_order ), base_month_totals AS ( SELECT DATE_TRUNC(month, order_timestamp) AS month, \'Online\' AS channel, COUNT(DISTINCT REPLACE(order_name,\'#\',\'\')) AS total_orders, COUNT(DISTINCT customer_id) AS total_users, SUM(gross_sales) AS total_revenue FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE gross_sales > 0 AND LOWER(order_status) NOT LIKE \'%cancel%\' GROUP BY month UNION ALL SELECT DATE_TRUNC( month, CASE WHEN vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN IFF(vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(transaction_date,\'MON DD, YYYY, HH12:MI AM\') END) AS month, \'Offline\' AS channel, COUNT(DISTINCT bill_no) AS total_orders, COUNT(DISTINCT TRIM(REGEXP_REPLACE(shopify_user_id,\',\',\'\'))) AS total_users, SUM(TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\'))) AS total_revenue FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary GROUP BY month ), base_month_totals_collapsed AS ( SELECT month, SUM(total_orders) AS total_orders, SUM(total_users) AS total_users, SUM(CASE WHEN channel = \'Online\' THEN total_revenue ELSE 0 END) AS total_revenue_online, SUM(CASE WHEN channel = \'Offline\' THEN total_revenue ELSE 0 END) AS total_revenue_offline, SUM(CASE WHEN channel = \'Online\' THEN total_users ELSE 0 END) AS total_users_online, SUM(CASE WHEN channel = \'Offline\' THEN total_users ELSE 0 END) AS total_users_offline, SUM(CASE WHEN channel = \'Online\' THEN total_orders ELSE 0 END) AS total_orders_online, SUM(CASE WHEN channel = \'Offline\' THEN total_orders ELSE 0 END) AS total_orders_offline, SUM(total_revenue) AS total_revenue FROM base_month_totals GROUP BY month ), base_week_totals AS ( SELECT DATE_TRUNC(\'week\', order_timestamp) AS week, \'Online\' AS channel, SUM(gross_sales) AS total_revenue FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE gross_sales > 0 AND LOWER(order_status) NOT LIKE \'%cancel%\' GROUP BY week UNION ALL SELECT DATE_TRUNC( \'week\', COALESCE( TRY_TO_TIMESTAMP(vouch_time, \'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(vouch_time, \'MON DD, YYYY, HH:MI AM\'), TRY_TO_TIMESTAMP(transaction_date,\'MON DD, YYYY, HH12:MI AM\') )) AS week, \'Offline\' AS channel, SUM(TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\'))) AS total_revenue FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary GROUP BY week ), base_week_totals_collapsed AS ( SELECT week, SUM(CASE WHEN channel = \'Online\' THEN total_revenue END) AS weekly_rev_online, SUM(CASE WHEN channel = \'Offline\' THEN total_revenue END) AS weekly_rev_offline FROM base_week_totals GROUP BY week ) SELECT co.month, order_ts, snitchx_ts, channel, order_id, co.shopify_user_id, gross_sales, discounts, net_sales, qty, cpf.coins_value, cpf.freebie_value, cpf.combined_value AS coins_plus_freebie, bmt.total_orders, bmt.total_users, bmt.total_revenue_online, bmt.total_revenue_offline, bmt.total_users_online, bmt.total_users_offline, bmt.total_orders_online, bmt.total_orders_offline, bmt.total_revenue, bwt.weekly_rev_online, bwt.weekly_rev_offline FROM combined_orders co LEFT JOIN snitchx_members s ON co.shopify_user_id = s.shopify_user_id LEFT JOIN coins_plus_freebie cpf ON co.month = cpf.month LEFT JOIN base_month_totals_collapsed bmt ON co.month = bmt.month LEFT JOIN base_week_totals_collapsed bwt ON DATE_TRUNC(\'week\', co.order_ts) = bwt.week ORDER BY month, order_id ); CREATE OR REPLACE TABLE snitch_db.maplemonk.snitchX_cohort_analysis_2 AS ( WITH SnitchX_Members AS ( SELECT DISTINCT TRIM(shopify_user_id) AS shopify_user_id, CASE WHEN membership_enrolled_date IS NOT NULL AND TRIM(membership_enrolled_date) <> \'\' THEN CONVERT_TIMEZONE( \'UTC\',\'Asia/Kolkata\', CASE WHEN membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP( CONCAT(TRIM(membership_enrolled_date),\':00\'), \'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(membership_enrolled_date)) END ) END AS snitchx_ts FROM snitch_db.maplemonk.s3_bucket_wallet_db WHERE membership_plan = \'SILVER\' ), MemID_to_Shopify_pre AS ( SELECT DISTINCT TRIM(ros.mem_id) AS mem_id, TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) AS shopify_user_id FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros WHERE ros.mem_id IS NOT NULL AND ros.mem_id <> \'NaN\' AND ros.mem_id NOT IN (\'9999999999\',\'1111111111\',\'1231231231\', \'1234567890\',\'5555555555\',\'1234567891\') AND ros.shopify_user_id IS NOT NULL UNION SELECT DISTINCT TRIM(ros.mem_id) AS mem_id, TRIM(REGEXP_REPLACE(f.customer_id, \',\', \'\')) AS shopify_user_id FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros JOIN snitch_db.maplemonk.FACT_ITEMS_SNITCH f ON RIGHT(REGEXP_REPLACE(f.phone, \'[^0-9]\', \'\'), 10) = RIGHT(REGEXP_REPLACE(ros.mem_id, \'[^0-9]\', \'\'), 10) WHERE ros.mem_id IS NOT NULL AND ros.mem_id <> \'NaN\' AND ros.mem_id NOT IN (\'9999999999\',\'1111111111\',\'1231231231\', \'1234567890\',\'5555555555\',\'1234567891\') AND f.customer_id IS NOT NULL ), MemID_to_Shopify AS ( SELECT mem_id, MAX(shopify_user_id) AS shopify_user_id FROM MemID_to_Shopify_pre WHERE shopify_user_id IS NOT NULL GROUP BY mem_id ), Offline_Sales AS ( SELECT ros.mem_id, map.shopify_user_id, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN CASE WHEN ros.vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(vouch_time,\'MON DD,YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(vouch_time,\'MON DD,YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD,YYYY, HH12:MI AM\') END AS order_ts, SUM(TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_value), \'[^0-9\.\-]\',\'\')) ) AS sales, SUM(TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_value), \'[^0-9\.\-]\', \'\'))) AS net_sales, ABS(SUM( TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_gross_value), \'[^0-9\.-]\',\'\')) - TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_value), \'[^0-9\.-]\',\'\')) )) AS discount, COUNT(DISTINCT ros.vouch_time) AS order_count, \'Offline\' AS channel FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros LEFT JOIN MemID_to_Shopify map ON ros.mem_id = map.mem_id WHERE ros.shopify_user_id IS NOT NULL OR map.shopify_user_id IS NOT NULL GROUP BY ros.mem_id, CASE WHEN vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN CASE WHEN vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(vouch_time,\'MON DD,YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(vouch_time,\'MON DD,YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date,\'YYYY-MM-DD HH24:MI:SS\') END, map.shopify_user_id, order_ts ), Online_Sales AS ( SELECT TRIM(CAST(customer_id AS STRING)) AS shopify_user_id, order_timestamp AS order_ts, SUM(IFNULL(gross_sales,0)) AS sales, SUM(CASE WHEN IS_REFUND = 0 THEN COALESCE(gross_sales, 0) ELSE 0 END) AS net_sales, SUM(IFNULL(discount,0)) - SUM(IFNULL(slashed_discount,0)) AS discount, COUNT(DISTINCT REPLACE(order_name,\'#\',\'\')) AS order_count, RIGHT(REGEXP_REPLACE(TRIM(CAST(phone AS STRING)),\'[^0-9]\', \'\'),10) AS phone, \'Online\' AS channel FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE LOWER(order_status) NOT LIKE \'%cancel%\' AND customer_id IS NOT NULL AND gross_sales <> 0 AND lower(tags) NOT LIKE \'%creator%\' AND lower(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND lower(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\', \'2422237\',\'2420623\',\'2429832\',\'2422378\', \'2428311\',\'2429064\',\'2428204\',\'2421343\', \'2431206\',\'2430491\',\'2426682\',\'2426487\', \'2426458\',\'2423575\',\'2422431\',\'2423612\', \'2426625\',\'2428117\',\'2426894\',\'2425461\', \'2426570\',\'2423455\',\'2430777\',\'2426009\', \'2428245\',\'2427269\',\'2430946\',\'2425821\', \'2429986\',\'2429085\',\'2422047\',\'2430789\', \'2420219\',\'2428341\',\'2430444\',\'2426866\', \'2431230\',\'2425839\',\'2430980\',\'2427048\', \'2430597\',\'2420499\',\'2431050\',\'2420271\', \'2426684\',\'2428747\',\'2423523\',\'2431171\', \'2430830\',\'2425325\',\'2428414\',\'2429054\', \'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') GROUP BY 1,2,7 ), All_Sales AS ( SELECT shopify_user_id, order_ts, sales, discount, order_count, net_sales, channel FROM Online_Sales UNION ALL SELECT shopify_user_id, order_ts, sales, discount, order_count, net_sales, channel FROM Offline_Sales ), Creator_Users AS ( SELECT DISTINCT TRIM(shopify_user_id) AS shopify_user_id FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db WHERE reason ILIKE \'%Creator%\' ), Channel_Tag AS ( SELECT shopify_user_id, MAX(CASE WHEN source=\'Online\' THEN 1 ELSE 0 END) AS has_online, MAX(CASE WHEN source=\'Offline\' THEN 1 ELSE 0 END) AS has_offline FROM ( SELECT DISTINCT shopify_user_id, \'Online\' AS source FROM Online_Sales UNION ALL SELECT DISTINCT COALESCE(ros.shopify_user_id,map.shopify_user_id), \'Offline\' AS source FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros LEFT JOIN SnitchX_Members map ON ros.mem_id = map.shopify_user_id WHERE ros.mem_id IS NOT NULL ) GROUP BY 1 ), Labeled_Sales AS ( SELECT a.shopify_user_id, a.order_ts, s.snitchx_ts, CASE WHEN a.order_ts <= s.snitchx_ts THEN \'Before\' ELSE \'After\' END AS period, a.sales, a.discount, a.order_count, a.net_sales, a.channel FROM All_Sales a JOIN SnitchX_Members s ON a.shopify_user_id = s.shopify_user_id ), first_credit AS ( SELECT shopify_user_id, amount AS welcome_points FROM ( SELECT shopify_user_id, amount, ROW_NUMBER() OVER (PARTITION BY shopify_user_id ORDER BY created_at) AS rn FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db WHERE type = \'POINTS_CREDIT\' AND reason NOT IN (\'Refund : Online\',\'Creator Coins Add: Online\',\'Coins Expired\', \'App purchase - Testing\',\'Ratings: Image Review\', \'Creator Coins Admin : Online\',\'Creator Coins Admin Remove: Online\', \'POINTS_CREDIT\',\'POINTS_DEBIT\',\'POINTS_EXPIRED\',\'App Refund\', \'App Purchase\',\'Creator Coins Remove: Online\', \'Coins Add: Bonus Coins - f14653\',\'App - Testing\', \'Review Images Added: c7b81107-852f-4ae7-a5ed-716ded3d1e31\', \'App refund - Testing\',\'Coins Add: Customer Issue Resolution - 323f94\', \'Refund Online\',\'Member Coins Add: Online\', \'Coins Add: Creator Order Placement - f14653\',\'Welcome gift\', \'credit_coins\') ) sub WHERE rn = 1 ), points_summary AS ( SELECT TRIM(wt.shopify_user_id) AS shopify_user_id, SUM(CASE WHEN wt.type = \'POINTS_CREDIT\' THEN wt.amount ELSE 0 END) AS reward_points_earned, SUM(CASE WHEN wt.type = \'POINTS_DEBIT\' AND wt.reason IN (\'Purchase : Online\', \'Purchase : Store\') THEN ABS(wt.amount) WHEN wt.type = \'POINTS_CREDIT\' AND wt.reason IN (\'Refund : Online\', \'Refund : Store\') THEN -wt.amount ELSE 0 END) AS reward_points_redeemed, SUM(CASE WHEN wt.reason = \'Birthday Bonus\' THEN wt.amount ELSE 0 END) AS birthday_points, SUM(CASE WHEN wt.reason = \'Welcome Bonus\' THEN wt.amount ELSE 0 END) + MAX(COALESCE(fc.welcome_points,0)) AS welcome_points, SUM(CASE WHEN wt.reason ILIKE \'%Bonus%\' AND reason NOT IN (\'Birthday Bonus\',\'Welcome Bonus\') THEN wt.amount ELSE 0 END) AS bonus_points FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db wt LEFT JOIN first_credit fc ON TRIM(wt.shopify_user_id)=fc.shopify_user_id WHERE wt.shopify_user_id IS NOT NULL AND wt.reason NOT IN (\'Creator Coins Add: Online\',\'Coins Expired\', \'App purchase - Testing\',\'Ratings: Image Review\', \'Creator Coins Admin : Online\',\'Creator Coins Admin Remove: Online\', \'POINTS_CREDIT\',\'POINTS_DEBIT\',\'POINTS_EXPIRED\',\'App Refund\', \'App Purchase\',\'Creator Coins Remove: Online\', \'Coins Add: Bonus Coins - f14653\',\'App - Testing\', \'Review Images Added: c7b81107-852f-4ae7-a5ed-716ded3d1e31\', \'App refund - Testing\',\'Coins Add: Customer Issue Resolution - 323f94\', \'Refund Online\',\'Member Coins Add: Online\', \'Coins Add: Creator Order Placement - f14653\',\'Welcome gift\', \'credit_coins\') GROUP BY 1 ), Freebies AS ( SELECT TRIM(CAST(shopify_user_id AS STRING)) AS shopify_user_id, COUNT(CASE WHEN gift_reference_id IS NOT NULL AND gift_reference_id <> \'\' THEN shopify_user_id END) AS freebies_received FROM snitch_db.maplemonk.streaks_streaks GROUP BY shopify_user_id ), Streaks AS ( SELECT shopify_user_id, MAX(CASE WHEN streak_count >= 4 AND streak_count < 7 THEN 4 WHEN streak_count >= 7 AND streak_count < 10 THEN 7 WHEN streak_count >= 10 AND streak_count < 13 THEN 10 WHEN streak_count >= 14 THEN 13 ELSE NULL END) AS mapped_streak, MAX(CASE WHEN gift_reference_id <> \'\' THEN TRY_TO_TIMESTAMP(streak_timestamp,\'DD-MM-YYYY HH24:MI\') ELSE NULL END) AS streak_redemption_date FROM snitch_db.maplemonk.streaks_streaks WHERE gift_reference_id <> \'\' AND streak_count > 1 GROUP BY shopify_user_id ), Streak_Previous_Order AS ( SELECT s.shopify_user_id, MAX(TRY_TO_TIMESTAMP(s.streak_timestamp,\'DD-MM-YYYY HH24:MI\')) AS streak_redemption_date, MAX(TRY_TO_TIMESTAMP(p.streak_timestamp,\'DD-MM-YYYY HH24:MI\')) AS streak_previous_order FROM snitch_db.maplemonk.streaks_streaks s LEFT JOIN snitch_db.maplemonk.streaks_streaks p ON s.shopify_user_id = p.shopify_user_id AND TRY_TO_TIMESTAMP(p.streak_timestamp,\'DD-MM-YYYY HH24:MI\') < TRY_TO_TIMESTAMP(s.streak_timestamp,\'DD-MM-YYYY HH24:MI\') WHERE s.gift_reference_id <> \'\' AND s.streak_count > 1 GROUP BY s.shopify_user_id ), Items_Ordered AS ( SELECT o.customer_id AS shopify_user_id, SUM(CASE WHEN o.order_timestamp < sm.snitchx_ts THEN IFNULL(o.quantity,0) ELSE 0 END) AS items_before_enrollment, SUM(CASE WHEN o.order_timestamp >= sm.snitchx_ts THEN IFNULL(o.quantity,0) ELSE 0 END) AS items_after_enrollment FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH o JOIN SnitchX_Members sm ON o.customer_id = sm.shopify_user_id WHERE o.customer_id IS NOT NULL AND LOWER(o.order_status) NOT LIKE \'%cancel%\' GROUP BY o.customer_id ), Returns AS ( SELECT f.customer_id AS shopify_user_id, COUNT( CASE WHEN f.order_timestamp >= CASE WHEN w.membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP(CONCAT(TRIM(w.membership_enrolled_date), \':00\'),\'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(w.membership_enrolled_date)) END THEN 1 END ) AS returns_after_enollment, SUM( CASE WHEN f.order_timestamp >= CASE WHEN w.membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP(CONCAT(TRIM(w.membership_enrolled_date), \':00\'),\'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(w.membership_enrolled_date)) END THEN f.line_item_sales ELSE 0 END ) AS return_value, COUNT( CASE WHEN f.order_timestamp < CAST( CASE WHEN w.membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP(CONCAT(TRIM(w.membership_enrolled_date), \':00\'),\'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(w.membership_enrolled_date)) END AS DATE) AND f.order_timestamp >= CAST( CASE WHEN w.membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP(CONCAT(TRIM(w.membership_enrolled_date), \':00\'),\'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(w.membership_enrolled_date)) END AS DATE) - INTERVAL \'12 months\' THEN 1 END ) AS returns_before_enollment FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH f JOIN snitch_db.maplemonk.s3_bucket_wallet_db w ON f.customer_id = w.shopify_user_id WHERE (f.IS_REFUND = 1 OR f.return_flag = 1) AND LOWER(f.order_status) NOT LIKE \'%cancel%\' AND w.membership_enrolled_date IS NOT NULL AND TRIM(w.membership_enrolled_date) <> \'\' GROUP BY f.customer_id ), Cohort_Builder AS ( SELECT shopify_user_id, snitchx_ts::DATE AS snitchx_date, MAX(CASE WHEN period=\'Before\' THEN order_ts END)::DATE AS not_snitchx_purchase_date, MAX(CASE WHEN period=\'Before\' AND order_ts = ( SELECT MAX(order_ts) FROM Labeled_Sales sub WHERE sub.shopify_user_id = Labeled_Sales.shopify_user_id AND sub.order_ts <= Labeled_Sales.snitchx_ts ) THEN net_sales ELSE 0 END) AS not_snitchx_purchase_value, MAX(CASE WHEN period=\'Before\' AND order_ts = ( SELECT MAX(order_ts) FROM Labeled_Sales sub WHERE sub.shopify_user_id = Labeled_Sales.shopify_user_id AND sub.order_ts <= Labeled_Sales.snitchx_ts ) THEN discount ELSE 0 END) AS not_snitchx_purchase_discount, MAX(CASE WHEN period=\'Before\' AND order_ts = ( SELECT MAX(order_ts) FROM Labeled_Sales sub WHERE sub.shopify_user_id = Labeled_Sales.shopify_user_id AND sub.order_ts <= Labeled_Sales.snitchx_ts ) THEN channel END) AS not_snitchx_purchase_channel, MAX(CASE WHEN period=\'After\' THEN order_ts END)::DATE AS last_purchase_date, MIN(CASE WHEN period=\'After\' THEN order_ts END)::DATE AS first_purchase_date, MIN(CASE WHEN period=\'Before\' THEN order_ts END)::DATE AS first_purchase_date_pre_enroll, SUM(CASE WHEN period=\'Before\' AND order_ts BETWEEN DATEADD(year,-1,snitchx_ts) AND snitchx_ts THEN IFNULL(net_sales,0) END) AS net_spend_l12, SUM(CASE WHEN period=\'Before\' AND order_ts BETWEEN DATEADD(year,-1,snitchx_ts) AND snitchx_ts THEN IFNULL(discount,0) END) AS total_discount_before, SUM(CASE WHEN period=\'Before\' AND order_ts BETWEEN DATEADD(year,-1,snitchx_ts) AND snitchx_ts THEN IFNULL(order_count,0) END) AS order_count_before, SUM(CASE WHEN period=\'After\' THEN discount ELSE 0 END) AS total_discount_after, SUM(CASE WHEN period=\'After\' THEN order_count ELSE 0 END) AS order_count_after, SUM(CASE WHEN period=\'After\' AND order_ts >= snitchx_ts THEN IFNULL(sales,0) END) AS net_sales_post_enrollment, SUM(CASE WHEN period=\'After\' AND order_ts >= snitchx_ts AND order_ts <= \'2025-03-15\' THEN IFNULL(sales,0) END) AS net_sales_post_enrollment_march15, SUM(CASE WHEN period=\'After\' AND order_ts >= snitchx_ts AND order_ts < DATEADD(month,1,snitchx_ts) THEN IFNULL(sales,0) END) AS sales_month_1, SUM(CASE WHEN period=\'After\' AND order_ts >= DATEADD(month,1,snitchx_ts) AND order_ts < DATEADD(month,2,snitchx_ts) THEN IFNULL(sales,0) END) AS sales_month_2, SUM(CASE WHEN period=\'After\' AND order_ts >= DATEADD(month,2,snitchx_ts) AND order_ts < DATEADD(month,3,snitchx_ts) THEN IFNULL(sales,0) END) AS sales_month_3, SUM(CASE WHEN period=\'After\' AND order_ts >= DATEADD(month,3,snitchx_ts) AND order_ts < DATEADD(month,4,snitchx_ts) THEN IFNULL(sales,0) END) AS sales_month_4, SUM(CASE WHEN period=\'After\' AND order_ts >= DATEADD(month,4,snitchx_ts) AND order_ts < DATEADD(month,5,snitchx_ts) THEN IFNULL(sales,0) END) AS sales_month_5, SUM(CASE WHEN period=\'After\' AND order_ts >= DATEADD(month,5,snitchx_ts) AND order_ts < DATEADD(month,6,snitchx_ts) THEN IFNULL(sales,0) END) AS sales_month_6, SUM(CASE WHEN period=\'After\' THEN net_sales END) AS net_sales, DATEDIFF(day,snitchx_ts::DATE,CURRENT_DATE()) AS days_since_enrollment, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATEADD(day,-365,snitchx_ts) AND order_ts <= DATEADD(day, DATEDIFF(day,snitchx_ts::DATE,CURRENT_DATE())-365, snitchx_ts) THEN IFNULL(sales,0) END) AS net_sales_baseline FROM Labeled_Sales GROUP BY 1,2 ), Month_Order AS ( SELECT c.shopify_user_id, c.first_purchase_date, SUM(CASE WHEN order_ts >= CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN DATE_TRUNC(\'MONTH\', NOT_SNITCHX_PURCHASE_DATE) ELSE DATE_TRUNC(\'MONTH\', FIRST_PURCHASE_DATE) END AND order_ts < DATE_TRUNC(\'MONTH\', DATEADD(month, 1, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) THEN IFNULL(sales, 0) END) AS new_sales_month_1, COUNT(CASE WHEN order_ts >= CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN DATE_TRUNC(\'MONTH\', NOT_SNITCHX_PURCHASE_DATE) ELSE DATE_TRUNC(\'MONTH\', FIRST_PURCHASE_DATE) END AND order_ts < DATE_TRUNC(\'MONTH\', DATEADD(month, 1, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) THEN order_ts END) AS new_orders_month_1, SUM(CASE WHEN order_ts >= DATE_TRUNC(\'MONTH\', DATEADD(month, 1, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) AND order_ts < DATE_TRUNC(\'MONTH\', DATEADD(month, 2, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) THEN IFNULL(sales, 0) END) AS new_sales_month_2, COUNT(CASE WHEN order_ts >= DATE_TRUNC(\'MONTH\', DATEADD(month, 1, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) AND order_ts < DATE_TRUNC(\'MONTH\', DATEADD(month, 2, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) THEN order_ts END) AS new_orders_month_2, SUM(CASE WHEN order_ts >= DATE_TRUNC(\'MONTH\', DATEADD(month, 2, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) AND order_ts < DATE_TRUNC(\'MONTH\', DATEADD(month, 3, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) THEN IFNULL(sales, 0) END) AS new_sales_month_3, COUNT(CASE WHEN order_ts >= DATE_TRUNC(\'MONTH\', DATEADD(month, 2, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) AND order_ts < DATE_TRUNC(\'MONTH\', DATEADD(month, 3, CASE WHEN DATEDIFF(DAY, NOT_SNITCHX_PURCHASE_DATE, SNITCHX_DATE) < 4 THEN NOT_SNITCHX_PURCHASE_DATE ELSE FIRST_PURCHASE_DATE END )) THEN order_ts END) AS new_orders_month_3 FROM Cohort_Builder c JOIN Labeled_Sales l ON l.shopify_user_id = c.shopify_user_id GROUP BY c.shopify_user_id, c.first_purchase_date ), Month_Order_YearAgo AS ( SELECT c.shopify_user_id, c.first_purchase_date, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,first_purchase_date)) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,1,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_1, COUNT(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,first_purchase_date)) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,1,first_purchase_date))) THEN order_ts END) AS prev_year_orders_month_1, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,1,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,2,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_2, COUNT(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,1,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,2,first_purchase_date))) THEN order_ts END) AS prev_year_orders_month_2, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,2,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,3,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_3, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,3,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,4,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_4, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,4,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,5,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_5, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,5,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,6,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_6, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,6,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,7,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_7, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,7,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,8,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_8, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,8,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,9,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_9, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,9,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,10,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_10, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,10,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,11,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_11, SUM(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,11,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,12,first_purchase_date))) THEN IFNULL(sales,0) END) AS prev_year_sales_month_12, COUNT(CASE WHEN period=\'Before\' AND order_ts >= DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,2,first_purchase_date))) AND order_ts < DATE_TRUNC(\'month\',DATEADD(year,-1,DATEADD(month,3,first_purchase_date))) THEN order_ts END) AS prev_year_orders_month_3 FROM Cohort_Builder c JOIN Labeled_Sales l ON l.shopify_user_id = c.shopify_user_id GROUP BY 1,2 ), Min_Enrollment_Date AS ( SELECT DATE_TRUNC(\'month\', MIN(snitchx_ts)) AS min_month FROM SnitchX_Members WHERE snitchx_ts IS NOT NULL ), Month_Series AS ( SELECT min_month AS month_start, DATEADD(day,-1,DATEADD(month,1,min_month)) AS month_end FROM Min_Enrollment_Date UNION ALL SELECT DATEADD(month,1,month_start), DATEADD(day,-1,DATEADD(month,2,month_start)) FROM Month_Series WHERE DATEADD(month,1,month_start) <= DATE_TRUNC(\'month\',CURRENT_DATE()) ), Month_Factors AS ( SELECT 4 AS month_num, 0.080 AS factor UNION ALL SELECT 5 AS month_num, 0.085 AS factor UNION ALL SELECT 6 AS month_num, 0.078 AS factor UNION ALL SELECT 7 AS month_num, 0.083 AS factor UNION ALL SELECT 8 AS month_num, 0.079 AS factor UNION ALL SELECT 9 AS month_num, 0.088 AS factor UNION ALL SELECT 10 AS month_num, 0.102 AS factor UNION ALL SELECT 11 AS month_num, 0.079 AS factor UNION ALL SELECT 12 AS month_num, 0.087 AS factor UNION ALL SELECT 1 AS month_num, 0.072 AS factor UNION ALL SELECT 2 AS month_num, 0.065 AS factor UNION ALL SELECT 3 AS month_num, 0.100 AS factor ), Enrollment_Months AS ( SELECT c.shopify_user_id, ms.month_start, ms.month_end, c.snitchx_date FROM Cohort_Builder c JOIN Month_Series ms ON ms.month_start >= DATE_TRUNC(\'month\',c.snitchx_date) AND ms.month_start <= DATE_TRUNC(\'month\',CURRENT_DATE()) ), Weighted_Factor AS ( SELECT e.shopify_user_id, SUM( CASE WHEN coverage_end >= coverage_start THEN (DATEDIFF(day,coverage_start,coverage_end)+1)::DECIMAL(10,2) * mf.factor / (DATEDIFF(day,e.month_start,e.month_end)+1) ELSE 0 END ) AS overall_net_factor FROM ( SELECT shopify_user_id, month_start, month_end, GREATEST(month_start,snitchx_date) AS coverage_start, LEAST(month_end,CURRENT_DATE()) AS coverage_end FROM Enrollment_Months ) e JOIN Month_Factors mf ON EXTRACT(MONTH FROM e.month_start) = mf.month_num GROUP BY 1 ), Phone_Map AS ( SELECT TRIM(shopify_user_id) AS shopify_user_id, \'+91\' || RIGHT(REGEXP_REPLACE(TRIM(mem_id),\'[^0-9]\',\'\'),10) AS phone FROM snitch_db.maplemonk.retail_orders_summary_retail_order_summary WHERE mem_id IS NOT NULL AND shopify_user_id != \'\' AND LENGTH(REGEXP_REPLACE(TRIM(mem_id),\'[^0-9]\',\'\')) >= 10 UNION ALL SELECT TRIM(customer_id) AS shopify_user_id, \'+91\' || RIGHT(REGEXP_REPLACE(TRIM(phone),\'[^0-9]\',\'\'),10) AS phone FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE phone IS NOT NULL AND customer_id IS NOT NULL AND LENGTH(REGEXP_REPLACE(TRIM(phone),\'[^0-9]\',\'\')) >= 10 ), Phone_Map_dedup AS ( SELECT shopify_user_id, MIN(phone) AS phone FROM Phone_Map GROUP BY shopify_user_id ), User_Cohorts AS ( SELECT c.shopify_user_id, pm.phone AS phone, c.snitchx_date, c.not_snitchx_purchase_date, c.not_snitchx_purchase_channel, c.not_snitchx_purchase_value, c.not_snitchx_purchase_discount, c.first_purchase_date, c.first_purchase_date_pre_enroll, c.last_purchase_date, c.net_spend_l12, c.net_sales, c.order_count_before, c.order_count_after, c.total_discount_before, c.total_discount_after, c.net_sales_post_enrollment, c.net_sales_post_enrollment_march15, c.sales_month_1, c.sales_month_2, c.sales_month_3, c.sales_month_4, c.sales_month_5, c.sales_month_6, mo.new_sales_month_1, mo.new_orders_month_1, mo.new_sales_month_2, mo.new_orders_month_2, mo.new_sales_month_3, mo.new_orders_month_3, mya.prev_year_sales_month_1, mya.prev_year_orders_month_1, mya.prev_year_sales_month_2, mya.prev_year_orders_month_2, mya.prev_year_sales_month_3, mya.prev_year_sales_month_4, mya.prev_year_sales_month_5, mya.prev_year_sales_month_6, mya.prev_year_sales_month_7, mya.prev_year_sales_month_8, mya.prev_year_sales_month_9, mya.prev_year_sales_month_10, mya.prev_year_sales_month_11, mya.prev_year_sales_month_12, mya.prev_year_orders_month_3, c.net_sales_baseline, c.days_since_enrollment, ps.reward_points_earned, ps.reward_points_redeemed, ps.welcome_points, ps.birthday_points, ps.bonus_points, f.freebies_received, s.mapped_streak, s.streak_redemption_date, p.streak_previous_order, DATEDIFF(day,p.streak_previous_order,s.streak_redemption_date) AS streak_TAT, COALESCE(i.items_before_enrollment,0) AS items_before_enrollment, r.returns_before_enollment, COALESCE(i.items_after_enrollment,0) AS items_after_enrollment, r.returns_after_enollment, r.return_value, CASE WHEN net_spend_l12 >= 15000 THEN \'15000+\' WHEN net_spend_l12 >= 13000 THEN \'13000-15000\' WHEN net_spend_l12 >= 11000 THEN \'11000-13000\' WHEN net_spend_l12 >= 9000 THEN \'9000-11000\' WHEN net_spend_l12 >= 7000 THEN \'7000-9000\' WHEN net_spend_l12 >= 5000 THEN \'5000-7000\' ELSE \'Below 5000\' END AS user_cohort, CASE WHEN net_spend_l12 >= 15000 THEN 6 WHEN net_spend_l12 >= 13000 THEN 5 WHEN net_spend_l12 >= 11000 THEN 4 WHEN net_spend_l12 >= 9000 THEN 3 WHEN net_spend_l12 >= 7000 THEN 2 WHEN net_spend_l12 >= 5000 THEN 1 ELSE 0 END AS cohort_id, CASE WHEN ct.has_online = 1 AND ct.has_offline = 1 THEN \'Both\' WHEN ct.has_online = 1 THEN \'Online\' WHEN ct.has_offline = 1 THEN \'Offline\' ELSE \'None\' END AS channel FROM Cohort_Builder c LEFT JOIN Channel_Tag ct ON c.shopify_user_id = ct.shopify_user_id LEFT JOIN points_summary ps ON c.shopify_user_id = ps.shopify_user_id LEFT JOIN Freebies f ON c.shopify_user_id = f.shopify_user_id LEFT JOIN Streaks s ON c.shopify_user_id = s.shopify_user_id LEFT JOIN Streak_Previous_Order p ON c.shopify_user_id = p.shopify_user_id LEFT JOIN Returns r ON r.shopify_user_id = c.shopify_user_id LEFT JOIN Items_Ordered i ON c.shopify_user_id = i.shopify_user_id LEFT JOIN Month_Order mo ON c.shopify_user_id = mo.shopify_user_id LEFT JOIN Month_Order_YearAgo mya ON c.shopify_user_id = mya.shopify_user_id LEFT JOIN Phone_Map_dedup pm ON c.shopify_user_id = pm.shopify_user_id ) SELECT uc.*, COALESCE(wf.overall_net_factor,0) AS overall_net_factor FROM User_Cohorts uc LEFT JOIN Weighted_Factor wf ON uc.shopify_user_id = wf.shopify_user_id WHERE uc.shopify_user_id NOT IN (SELECT shopify_user_id FROM Creator_Users) ); CREATE OR REPLACE TABLE snitch_db.maplemonk.snitchx_cohort_analysis_3 ( AS WITH points_spent AS ( SELECT tx.ID AS transaction_id, tx.TYPE, tx.AMOUNT, tx.REASON, tx.CREATED_AT AS transaction_created_at, tx.UPDATED_AT AS transaction_updated_at, tx.POINTS_EXPIRY, tx.MEMBERSHIP_PLAN AS transaction_membership_plan, tx.SHOPIFY_USER_ID, tx.SHOPIFY_ORDER_ID, tx.POINTS_BATCH_ID, tx.BALANCE_AFTER_TRANSACTION, w.ID AS wallet_id, w.CASH_BALANCE, w.POINTS_BALANCE, w.MEMBERSHIP_PLAN AS wallet_membership_plan, w.MEMBERSHIP_VALID_TILL, TO_CHAR( COALESCE( TRY_TO_TIMESTAMP(w.membership_enrolled_date, \'YYYY-MM-DD HH24:MI:SS.FF\'), TRY_TO_TIMESTAMP(w.membership_enrolled_date, \'DD-MM-YYYY HH24:MI\') ), \'YYYY-MM-DD HH24:MI:SS\') AS membership_enrolled_date FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db tx LEFT JOIN snitch_db.maplemonk.s3_bucket_wallet_db w ON tx.SHOPIFY_USER_ID = w.SHOPIFY_USER_ID WHERE tx.MEMBERSHIP_PLAN = \'SILVER\' AND w.MEMBERSHIP_PLAN = \'SILVER\' AND tx.REASON NOT IN ( \'Refund : Online\',\'Creator Coins Add: Online\',\'Coins Expired\', \'App purchase - Testing\',\'Ratings: Image Review\', \'Creator Coins Admin : Online\',\'Creator Coins Admin Remove: Online\', \'POINTS_CREDIT\',\'POINTS_DEBIT\',\'POINTS_EXPIRED\',\'App Refund\', \'App Purchase\',\'Creator Coins Remove: Online\', \'Coins Add: Bonus Coins - f14653\',\'App - Testing\', \'Review Images Added: c7b81107-852f-4ae7-a5ed-716ded3d1e31\', \'App refund - Testing\',\'Coins Add: Customer Issue Resolution - 323f94\', \'Refund Online\',\'Member Coins Add: Online\', \'Coins Add: Creator Order Placement - f14653\',\'Welcome gift\', \'credit_coins\' ) ), freebies AS ( SELECT shopify_user_id, COUNT(CASE WHEN gift_reference_id IS NOT NULL AND gift_reference_id != \'\' THEN 1 END) AS freebies_received FROM streaks_streaks GROUP BY shopify_user_id ), first_credit AS ( SELECT shopify_user_id, CASE WHEN reason != \'Welcome Bonus\' THEN amount ELSE 0 END AS welcome_points FROM ( SELECT shopify_user_id, reason, amount, ROW_NUMBER() OVER (PARTITION BY shopify_user_id ORDER BY created_at) AS rn FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db WHERE type = \'POINTS_CREDIT\' AND reason NOT IN ( \'Refund : Online\',\'Creator Coins Add: Online\',\'Coins Expired\', \'App purchase - Testing\',\'Ratings: Image Review\', \'Creator Coins Admin : Online\',\'Creator Coins Admin Remove: Online\', \'POINTS_CREDIT\',\'POINTS_DEBIT\',\'POINTS_EXPIRED\',\'App Refund\', \'App Purchase\',\'Creator Coins Remove: Online\', \'Coins Add: Bonus Coins - f14653\',\'App - Testing\', \'Review Images Added: c7b81107-852f-4ae7-a5ed-716ded3d1e31\', \'App refund - Testing\',\'Coins Add: Customer Issue Resolution - 323f94\', \'Refund Online\',\'Member Coins Add: Online\', \'Coins Add: Creator Order Placement - f14653\',\'Welcome gift\', \'credit_coins\' ) ) sub WHERE rn = 1 AND reason != \'Welcome Bonus\' ), batch_to_reason AS ( SELECT DISTINCT points_batch_id, reason FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db WHERE type = \'POINTS_CREDIT\' AND reason IN (\'Welcome Bonus\', \'Birthday Bonus\', \'Festive Bonus\') AND points_batch_id IS NOT NULL ), debits_with_type AS ( SELECT wt.shopify_user_id, wt.amount, b.reason AS bonus_reason FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db wt JOIN batch_to_reason b ON wt.points_batch_id = b.points_batch_id WHERE wt.type = \'POINTS_DEBIT\' AND wt.reason IN (\'Purchase : Store\',\'Purchase : Online\') ), bonus_debit_summary AS ( SELECT shopify_user_id, SUM(CASE WHEN bonus_reason = \'Welcome Bonus\' THEN amount ELSE 0 END) AS welcome_bonus_debit, SUM(CASE WHEN bonus_reason = \'Birthday Bonus\' THEN amount ELSE 0 END) AS birthday_bonus_debit, SUM(CASE WHEN bonus_reason = \'Festive Bonus\' THEN amount ELSE 0 END) AS festive_bonus_debit FROM debits_with_type GROUP BY shopify_user_id ) SELECT ps.SHOPIFY_USER_ID, ps.MEMBERSHIP_ENROLLED_DATE, (SUM(CASE WHEN ps.REASON = \'Welcome Bonus\' AND ps.TYPE = \'POINTS_CREDIT\' THEN ps.AMOUNT ELSE 0 END) + MAX(COALESCE(fc.welcome_points,0))) AS welcome_bonus_credit, COALESCE(bds.welcome_bonus_debit, 0) AS welcome_bonus_debit, SUM(CASE WHEN ps.REASON = \'Purchase : Online\' AND ps.TYPE = \'POINTS_CREDIT\' THEN ps.AMOUNT ELSE 0 END) AS purchase_online_credit, SUM(CASE WHEN ps.REASON = \'Purchase : Online\' AND ps.TYPE = \'POINTS_DEBIT\' THEN ps.AMOUNT ELSE 0 END) AS purchase_online_debit, SUM(CASE WHEN ps.REASON = \'Purchase : Store\' AND ps.TYPE = \'POINTS_CREDIT\' THEN ps.AMOUNT ELSE 0 END) AS purchase_store_credit, SUM(CASE WHEN ps.REASON = \'Purchase : Store\' AND ps.TYPE = \'POINTS_DEBIT\' THEN ps.AMOUNT ELSE 0 END) AS purchase_store_debit, SUM(CASE WHEN ps.REASON = \'Festive Bonus\' AND ps.TYPE = \'POINTS_CREDIT\' THEN ps.AMOUNT ELSE 0 END) AS festive_bonus_credit, COALESCE(bds.festive_bonus_debit, 0) AS festive_bonus_debit, SUM(CASE WHEN ps.REASON = \'Birthday Bonus\' AND ps.TYPE = \'POINTS_CREDIT\' THEN ps.AMOUNT ELSE 0 END) AS birthday_bonus_credit, COALESCE(bds.birthday_bonus_debit, 0) AS birthday_bonus_debit, COALESCE(f.freebies_received, 0) AS freebies_received FROM points_spent ps LEFT JOIN freebies f ON ps.SHOPIFY_USER_ID = f.shopify_user_id LEFT JOIN first_credit fc ON ps.shopify_user_id = fc.shopify_user_id LEFT JOIN bonus_debit_summary bds ON ps.shopify_user_id = bds.shopify_user_id GROUP BY ps.SHOPIFY_USER_ID, ps.MEMBERSHIP_ENROLLED_DATE, f.freebies_received, bds.welcome_bonus_debit, bds.festive_bonus_debit, bds.birthday_bonus_debit ); CREATE OR REPLACE TABLE snitchx_redemption AS ( WITH SnitchX_Members AS ( SELECT DISTINCT TRIM(shopify_user_id) AS shopify_user_id, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', CASE WHEN membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP( CONCAT(TRIM(membership_enrolled_date),\':00\'), \'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(membership_enrolled_date)) END ) AS membership_enrolled_date FROM snitch_db.maplemonk.s3_bucket_wallet_db WHERE membership_plan = \'SILVER\' ), online_orders AS ( SELECT TRIM(CAST(customer_id AS STRING)) AS shopify_user_id, REGEXP_REPLACE( REPLACE(order_name,\'#\',\'\'), \'\\.0$\' ) AS order_ref, order_timestamp AS order_ts, \'Online\' AS channel FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE LOWER(order_status) NOT LIKE \'%cancel%\' AND customer_id IS NOT NULL AND is_refund = 0 AND gross_sales <> 0 AND lower(tags) NOT LIKE \'%creator%\' AND lower(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND lower(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' AND tags NOT IN (\'FLITS_LOGICERP\') GROUP by customer_id, order_name, order_ts ), offline_orders AS ( SELECT TRIM(CAST(shopify_user_id AS STRING)) AS shopify_user_id, bill_no AS order_ref, CASE WHEN vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN CASE WHEN vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(transaction_date,\'MON DD, YYYY, HH12:MI AM\') END AS order_ts, TRY_TO_NUMBER(REPLACE(points_redeemed, \',\', \'\')) AS points_redeemed, \'Offline\' AS channel FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ), all_orders AS ( SELECT shopify_user_id, order_ref, order_ts, NULL::NUMBER AS points_redeemed, channel FROM online_orders UNION ALL SELECT shopify_user_id, order_ref, order_ts, points_redeemed, channel FROM offline_orders ), orders_after_enrolment AS ( SELECT o.* FROM all_orders o JOIN SnitchX_Members m USING (shopify_user_id) WHERE o.order_ts >= m.membership_enrolled_date ), wallet_running AS ( SELECT wt.shopify_user_id, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', wt.created_at) AS created_at, COALESCE(wt.balance_after_transaction, 0) AS running_balance FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db wt ), online_points_redeemed AS ( SELECT REGEXP_REPLACE( REPLACE(shopify_order_number,\'#\',\'\'), \'\\.0$\' ) AS order_ref, shopify_user_id, SUM(ABS(amount)) AS points_redeemed FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db WHERE type = \'POINTS_DEBIT\' AND reason = \'Purchase : Online\' GROUP BY 1,2 ), balance_before AS ( SELECT o.order_ref, o.shopify_user_id, w.running_balance AS points_before_order FROM orders_after_enrolment o JOIN wallet_running w ON w.shopify_user_id = o.shopify_user_id AND w.created_at < o.order_ts QUALIFY ROW_NUMBER() OVER ( PARTITION BY o.order_ref, o.shopify_user_id ORDER BY w.created_at DESC ) = 1 ) SELECT o.shopify_user_id, m.membership_enrolled_date, CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', o.order_ts) AS order_date, o.order_ref, COALESCE(b.points_before_order,0) AS points_before_order, COALESCE(o.points_redeemed, r.points_redeemed, 0) AS points_redeemed, o.channel FROM orders_after_enrolment o JOIN SnitchX_Members m USING (shopify_user_id) LEFT JOIN balance_before b USING (order_ref, shopify_user_id) LEFT JOIN online_points_redeemed r USING (order_ref, shopify_user_id) ORDER BY order_date DESC, shopify_user_id );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            